const countDistinctMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const bonusForVariety = (distinctTypeCount: number): number => {
  const typesBeyondBase = distinctTypeCount - TYPES_INCLUDED_IN_BASE_BONUS;
  return typesBeyondBase > 0
    ? BONUS_PER_EXTRA_TYPE * typesBeyondBase
    : BASE_BONUS;
};

export const scoreArmy = (army: Card[]): number =>
  army.reduce((score, card, index) => {
    if (card.monster !== SPHINX) return score;
    const otherCards = army.filter((_, other) => other !== index);
    return (
      score + SPHINX_POINTS + bonusForVariety(countDistinctMonsterTypes(otherCards))
    );
  }, 0);

input.new_string:
const distinctMonsterTypes = (army: Card[]): Set<string> =>
  new Set(army.map((card) => card.monster));

const bonusForVariety = (distinctTypeCount: number): number => {
  const typesBeyondBase = distinctTypeCount - TYPES_INCLUDED_IN_BASE_BONUS;
  return typesBeyondBase > 0
    ? BONUS_PER_EXTRA_TYPE * typesBeyondBase
    : BASE_BONUS;
};

const countCardsOfType = (army: Card[], monster: string): number =>
  army.filter((card) => card.monster === monster).length;

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = countCardsOfType(army, SPHINX);
  const typesInArmy = distinctMonsterTypes(army).size;

  // A Sphinx counts the types among the OTHER cards. Sphinx is still one of
  // those types whenever a second Sphinx is present; a lone Sphinx is not.
  const typesSeenByEachSphinx =
    sphinxCount > 1 ? typesInArmy : typesInArmy - 1;

  return sphinxCount * (SPHINX_POINTS + bonusForVariety(typesSeenByEachSphinx));
};

