cat > /tmp/equiv.mjs <<'EOF'
const SPHINX="sphinx", TYPES_BASE=3, SPHINX_POINTS=1, BASE_BONUS=1, PER_EXTRA=2;
const bonus=n=>{const b=n-TYPES_BASE;return b>0?PER_EXTRA*b:BASE_BONUS;};

// ORIGINAL: per-card, excludes own card by index
const oldScore=army=>army.reduce((s,card,i)=>{
  if(card.monster!==SPHINX)return s;
  const others=army.filter((_,o)=>o!==i);
  return s+SPHINX_POINTS+bonus(new Set(others.map(c=>c.monster)).size);
},0);

// NEW: closed form
const newScore=army=>{
  const sc=army.filter(c=>c.monster===SPHINX).length;
  const t=new Set(army.map(c=>c.monster)).size;
  const seen=sc>1?t:t-1;
  return sc*(SPHINX_POINTS+bonus(seen));
};

const pool=["sphinx","chimera","orthrus","zombie","hydra","cyclops"];
let checked=0, bad=[];
// exhaustive over all multisets of size 0..6 from the pool
const rec=(arr,start,max)=>{
  const army=arr.map(m=>({monster:m}));
  const a=oldScore(army), b=newScore(army);
  checked++;
  if(a!==b) bad.push({army:arr.join(","),old:a,new:b});
  if(arr.length===max)return;
  for(let i=start;i<pool.length;i++) rec([...arr,pool[i]],i,max);
};
for(let n=0;n<=6;n++) rec([],0,n);

// also permutations-with-repetition up to length 5 (order + duplicates)
const rec2=(arr,max)=>{
  if(arr.length>0){
    const army=arr.map(m=>({monster:m}));
    const a=oldScore(army), b=newScore(army);
    checked++;
    if(a!==b) bad.push({army:arr.join(","),old:a,new:b});
  }
  if(arr.length===max)return;
  for(const m of pool) rec2([...arr,m],max);
};
rec2([],5);

console.log("cases checked:",checked);
console.log("mismatches:",bad.length);
console.log(JSON.stringify(bad.slice(0,12),null,1));
EOF
node /tmp/equiv.mjs

cat > /tmp/edge.mts <<'EOF'
import { scoreArmy } from "./src/sphinx-score.js";
console.log("empty army:", scoreArmy([]));
console.log("no sphinx, 1 type:", scoreArmy([{monster:"chimera"}]));
console.log("no sphinx, 5 types:", scoreArmy([1,2,3,4,5].map(i=>({monster:"m"+i}))));
console.log("lone sphinx only:", scoreArmy([{monster:"sphinx"}]));
console.log("two sphinx only:", scoreArmy([{monster:"sphinx"},{monster:"sphinx"}]));
EOF
npx tsx /tmp/edge.mts 2>&1 | tail -10

